<?php $pageTitle = 'Owner sign in'; ?>
<section class="auth-wrap owner-login-wrap"><div class="auth-aside"><span class="eyebrow">Riz Catering · Owner portal</span><h1>Business management, kept private.</h1><p>Sign in to review reservations, manage offerings, and view business reports.</p></div><form class="auth-form" method="post" action="<?= rc_e(rc_endpoint()) ?>" autocomplete="on"><?= rc_csrf_field() ?><input type="hidden" name="action" value="owner-login"><h2>Owner sign in</h2><?php if (($_GET['reason'] ?? '') === 'expired'): ?><p class="flash flash-error" role="status">Session expired due to 24 hours of inactivity. Please log in again.</p><?php endif; ?><div class="field"><label for="owner-email">Owner email</label><input id="owner-email" name="email" type="email" autocomplete="username" required></div><div class="field"><label for="owner-password">Password</label><input id="owner-password" name="password" type="password" autocomplete="current-password" required></div><button class="button form-submit" type="submit">Sign in to owner portal</button><?php if (!empty($ownerSetupAvailable) && !empty($setupConfigured)): ?><p class="muted">Setting up this system for the first time? <a class="text-link" href="<?= rc_url('install') ?>">Create the owner account</a>.</p><?php elseif (!empty($ownerSetupAvailable)): ?><p class="muted">Owner setup is waiting for the server's RIZ_OWNER_SETUP_KEY configuration.</p><?php endif; ?></form></section>
